def get_S(k, n):
    S = [1] * n
    for _ in range(k):
        new_S = []
        for i in range(len(S) - 1):
            new_S.append(S[i])
            new_S.append(S[i] + S[i+1])
        new_S.append(S[-1])
        S = new_S
    return S

for k in range(4):
    print(f"k={k}: {get_S(k, 4)}")
